              padding: [token("spacing.xl"), token("spacing.xl"), token("spacing.lg")],
              gap: token("spacing.sm"),
              borderRadius: { topLeft: token("radii.md"), topRight: token("radii.md") },
            }}
          >
            <Text
              style={{
                fontSize: token("fontSizes.small"),
