              alt={brand.logo.alt}
              style={{ width: 120 }}
            />
            <Row style={{ gap: token("spacing.lg") }}>
              <Column style={{ gap: 2 }}>
                <Text
                  style={{
                    fontSize: 10,
                    fontWeight: 700,
                    letterSpacing: 1.5,
